\label{abelianquaexten}
		Let $M/F$ be a quadratic unramified extension of  number fields.  Then $h_2(M)=2$ if and only if $h_2(F)=4$ and $F^{(1)}=F^{(2)}$, where 
		$F^{(1)}$ (resp. $ F^{(2)}$) the Hilbert $2$-class field  of $F$ (resp. $F^{(1)}$). In fact, by class field theory we have the following diagram: 
		\[
		\xymatrix@C=1.8cm{
			F
			\ar@{-}[r]
			\ar@/^1.5pc/[rr]^{A(F)}
			&
			M
			\ar@{-}[r]
			\ar@/_1.5pc/[rr]_{A(M)}
			&
			F^{(1)}
			\ar@{-}[r]
			&
			M^{(1)}
			\ar@{-}[r]
			&
			\mathcal{L}(M)=\mathcal{L}(F)
		}
		\]
		
		
		Here $\mathcal{L}(k)$ denotes the maximal unramified $2$-extension of a number field $k$.	So one deduces directly the result.

\label{unitspp1q1q2}
Let $p$, $p_1$, $q_1$  and $q_2$ be distinct prime numbers such that $p\equiv p_1\equiv-q_1\equiv-q_2\equiv1\pmod4$. Put $\varepsilon_{pp_1q_1q_2}=a+b\sqrt{pp_1q_1q_2}$ (resp. $\varepsilon_{p_1q_1q_2}=x+y\sqrt{p_1q_1q_2}$)   the fundamental unit of $\mathbb{Q}(\sqrt{pp_1q_1q_2})$ (resp. $\mathbb{Q}(\sqrt{p_1q_1q_2})$) for some integers or semi-integers $a$, $b$, $x$ and $y$. We have: 
\begin{enumerate}[$1)$]
	\item If $\left(\frac{p}{p_1}\right)=\left(\frac{p}{q_1}\right)=\left(\frac{p}{q_2}\right)=\left(\frac{p_1}{q_1}\right)=-\left(\frac{p_1}{q_2}\right)=-1,$ then \begin{enumerate}[$a)$]
		\item $2pq_1(a\pm1)$ and $2q_2(x\pm1)$  are  squares in $\mathbb{Q}$,
		
		\item The unit group of $\mathbb{Q}(\sqrt{p},\sqrt{p_1q_1q_2})$ is given by $\langle{-1,\varepsilon_{p},\varepsilon_{p_1q_1q_2},\varepsilon_{pp_1q_1q_2}\rangle}$.
	\end{enumerate}
	\item If $\left(\frac{p}{p_1}\right)=-\left(\frac{p}{q_1}\right)=\left(\frac{p}{q_2}\right)=\left(\frac{p_1}{q_1}\right)=-\left(\frac{p_1}{q_2}\right)=\left(\frac{q_1}{q_2}\right)=-1,$ then 
	\begin{enumerate}[$a)$]
		\item $2pq_1(a+1)$ and $2q_2(x+1)$ are squares in $\mathbb{Q}$,
		\item The unit group of $\mathbb{Q}(\sqrt{p},\sqrt{p_1q_1q_2})$ is given by $\langle{-1,\varepsilon_{p},\varepsilon_{p_1q_1q_2},\varepsilon_{pp_1q_1q_2}\rangle}$.
	\end{enumerate}
\end{enumerate}

\label{ZekTAo}
Let \( d \equiv 1 \pmod{4} \) be a positive square free integer and \( \varepsilon_d = x + y\sqrt{d} \) be the fundamental unit of \( \mathbb{Q}(\sqrt{d}) \). Assume \( N(\varepsilon_d) = 1 \), then
\begin{enumerate}[$1)$]
	\item \( x + 1 \) and \( x - 1 \) are not squares in \( \mathbb{Q} \).
	\item For all integer \(\delta \) dividing \( d \), \( \delta(x + 1) \) and \( \delta(x - 1) \) are not squares in \( \mathbb{Q} \).
\end{enumerate}

\cite[Lemma 6]{BS25}\label{unitsrs}
Let \( r, s \) be distinct primes \( \equiv 3 \mod 4 \). Then 
\begin{enumerate}[$1)$]
	\item  $\sqrt{\varepsilon_{rs}} = \frac{1}{2}(a\sqrt{r} + b\sqrt{s}), \text{ for some } a, b \in \mathbb{Z} \text{ with } a \equiv b \mod 2;$   
	moreover, $ \frac{1}{4}(a^2r - b^2s) = (r/s) = -(s/r)$; 
	
	\item  $\sqrt{\varepsilon_{2r}} = a\sqrt{2} + b\sqrt{r}, \text{ for some } a, b \in \mathbb{Z};$   
	moreover,  $a^2 - b^2 = (2/r) = (-r/2);$
	\item  $\sqrt{\varepsilon_r} = \frac{1}{2}(a\sqrt{2r} + b\sqrt{2}), \text{ for some odd } a, b \in \mathbb{Z};$  
	moreover,  $\frac{1}{2}(a^2r - b^2) = -(r/2). $
\end{enumerate}
